SELECT 
FROM dynamic_config
WHERE env = #{env}
AND (
    version_range = #{version}
    OR (version_range LIKE '%-%' AND
        SUBSTRING_INDEX(version_range, '-', 1) <= #{version}
        AND SUBSTRING_INDEX(version_range, '-', -1) >= #{version})
)
ORDER BY created_at DESC
LIMIT 1

